begin;
create temp table ig_check_results(name text primary key) on commit drop;
create function pg_temp.ig_assert(ok boolean,label text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'Check failed: %',label;end if;insert into ig_check_results values(label);end$$;
do $$
declare owner_id uuid; other_id uuid; session_id uuid; req uuid; other_req uuid; p jsonb;r jsonb;rejected boolean;secret text=repeat('a',64);
begin
 select id into owner_id from auth.users where email='akm@indiagully.com';
 select id into other_id from auth.users where email='pavan@indiagully.com';
 select id into session_id from auth.sessions where user_id=owner_id order by created_at desc limit 1;
 update ig_private.integration_root set secret_hash=encode(extensions.digest(convert_to(secret,'UTF8'),'sha256'),'hex');
 insert into public.ig_payment_requests(user_id,invoice_ref,description,practice,amount_paise,status,provider_order_id,mode,expires_at) values(owner_id,'ROLLBACK-QA-'||gen_random_uuid(),'Synthetic transaction rolled back. No provider operation.','horeca',1000,'pending','order_RollbackCheck','test',now()+interval '1 hour') returning id into req;
 p=jsonb_build_object('id',req,'provider_order_id','order_RollbackCheck','provider_payment_id','pay_RollbackCheck','amount_paise',1000,'currency','INR','provider_status','captured','captured',true,'refunded_paise',0,'source','callback');
 rejected=false;begin perform public.ig_payment_reconcile('wrong',p);exception when insufficient_privilege then rejected=true;end;perform pg_temp.ig_assert(rejected,'Wrong server secret denied');
 rejected=false;begin perform public.ig_payment_reconcile(secret,p||'{"amount_paise":999}');exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Wrong payment amount denied');
 r=public.ig_payment_reconcile(secret,p||'{"provider_status":"authorized","captured":false}');perform pg_temp.ig_assert(r->>'status'='pending','Authorization is not capture');
 r=public.ig_payment_reconcile(secret,p||'{"provider_status":"failed","captured":false}');perform pg_temp.ig_assert(r->>'status'='pending','Failed attempt does not mark request paid');
 p=p||jsonb_build_object('source','webhook','event_id','rollback-event-capture','body_hash',repeat('b',64),'event_kind','payment.captured');
 r=public.ig_payment_reconcile(secret,p);perform pg_temp.ig_assert(r->>'status'='paid','Capture marks paid');
 perform pg_temp.ig_assert(r->>'last_webhook_at' is not null,'Capture webhook timestamp persists');
 r=public.ig_payment_reconcile(secret,p);perform pg_temp.ig_assert(r->>'duplicate'='true','Repeated webhook is idempotent');
 perform pg_temp.ig_assert((select count(*)=1 from ig_private.payment_events where request_id=req),'Duplicate does not create another receipt');
 rejected=false;begin perform public.ig_payment_reconcile(secret,p||jsonb_build_object('body_hash',repeat('c',64)));exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Event ID with different bytes denied');
 p=p-'event_id'-'body_hash'-'event_kind';p=p||'{"source":"admin"}';
 r=public.ig_payment_reconcile(secret,p||'{"refunded_paise":250}');perform pg_temp.ig_assert((r->>'refunded_paise')::int=250,'Partial refund recorded');
 r=public.ig_payment_reconcile(secret,p);perform pg_temp.ig_assert((r->>'refunded_paise')::int=250,'Older response cannot decrease refund');
 r=public.ig_payment_reconcile(secret,p||'{"provider_status":"refunded","refunded_paise":1000}');perform pg_temp.ig_assert((r->>'refunded_paise')::int=1000,'Full refund recorded');
 r=public.ig_payment_reconcile(secret,p||'{"provider_status":"failed","captured":false,"provider_payment_id":"pay_FailedLater"}');perform pg_temp.ig_assert(r->>'status'='paid' and r->>'provider_status'='refunded','Late failure cannot undo capture or refund');
 rejected=false;begin perform public.ig_payment_reconcile(secret,p||'{"refunded_paise":1001}');exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Refund above captured total denied');
 rejected=false;begin perform public.ig_payment_reconcile(secret,p||'{"provider_payment_id":"pay_SecondCapture"}');exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Different captured payment denied');
 perform pg_temp.ig_assert(not has_table_privilege('authenticated','ig_private.payment_events','select') and not has_table_privilege('anon','ig_private.payment_events','select'),'Receipt log not publicly readable');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'session_id',session_id,'aal','aal1','role','authenticated')::text,true);
 rejected=false;begin perform public.ig_payment_reconciliation_access(jsonb_build_object('id',req,'staff',true));exception when insufficient_privilege then rejected=true;end;perform pg_temp.ig_assert(rejected,'Staff reconciliation requires MFA');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'session_id',session_id,'aal','aal2','role','authenticated')::text,true);
 perform public.ig_payment_reconciliation_access(jsonb_build_object('id',req,'staff',true));perform pg_temp.ig_assert(true,'Owner can reconcile an assigned payment');
 rejected=false;begin perform public.ig_payment_reconciliation_access(jsonb_build_object('id',req,'staff',true));exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Reconciliation throttles rapid repeats');
 insert into public.ig_payment_requests(user_id,invoice_ref,description,practice,amount_paise,status,provider_order_id,mode,expires_at) values(other_id,'ROLLBACK-QA-'||gen_random_uuid(),'Synthetic transaction rolled back. No provider operation.','horeca',1000,'pending','order_RollbackOther','test',now()+interval '1 hour') returning id into other_req;
 rejected=false;begin perform public.ig_payment_reconciliation_access(jsonb_build_object('id',other_req,'staff',false));exception when insufficient_privilege then rejected=true;end;perform pg_temp.ig_assert(rejected,'Customer refresh cannot target another account');
 update public.ig_profiles set roles=array['client'] where id=owner_id;
 rejected=false;begin perform public.ig_payment_reconciliation_access(jsonb_build_object('id',other_req,'staff',true));exception when insufficient_privilege then rejected=true;end;perform pg_temp.ig_assert(rejected,'Client role cannot use staff reconciliation');
end$$;
select count(*) as passed,array_agg(name order by name) as checks from ig_check_results;
rollback;
